//! The window's views (kit, owned by the shell): which view shows, Back and
//! Escape, filling the view that shows from the latest snapshot, and the
//! armed actions. Views do not edit this file: each has its module
//! (`view::<name>`) with a `fill` that the router calls, and a `wire` that
//! the window calls once when it is created.
#![forbid(unsafe_code)]

use std::time::Instant;

use n8tray_core::model::{HostSnapshot, WarningView};

use super::confirm::Confirms;
use super::icons::Icons;
use super::{about, all_apps, details, history, hub, panel, settings};
#[cfg(debug_assertions)]
use crate::ui::Gallery;
use crate::ui::{
    AboutModel, AllAppsModel, DetailsModel, FlyoutWindow, HistoryModel, HubModel, Nav, PanelModel,
    Reveal, RowFocus, SettingsModel, Theme, View,
};
use slint::ComponentHandle;

/// The window's globals, for the views' `fill` and `wire`: the shell's
/// window and the gallery both have them.
pub trait Models {
    fn hub(&self) -> HubModel<'_>;
    fn all_apps(&self) -> AllAppsModel<'_>;
    fn panel(&self) -> PanelModel<'_>;
    fn details(&self) -> DetailsModel<'_>;
    fn settings(&self) -> SettingsModel<'_>;
    fn about(&self) -> AboutModel<'_>;
    fn history(&self) -> HistoryModel<'_>;
    fn row_focus(&self) -> RowFocus<'_>;
    fn reveal(&self) -> Reveal<'_>;
    fn theme(&self) -> Theme<'_>;
    fn nav(&self) -> Nav<'_>;
}

macro_rules! models {
    ($t:ty) => {
        impl Models for $t {
            fn hub(&self) -> HubModel<'_> {
                self.global()
            }
            fn all_apps(&self) -> AllAppsModel<'_> {
                self.global()
            }
            fn panel(&self) -> PanelModel<'_> {
                self.global()
            }
            fn details(&self) -> DetailsModel<'_> {
                self.global()
            }
            fn settings(&self) -> SettingsModel<'_> {
                self.global()
            }
            fn about(&self) -> AboutModel<'_> {
                self.global()
            }
            fn history(&self) -> HistoryModel<'_> {
                self.global()
            }
            fn row_focus(&self) -> RowFocus<'_> {
                self.global()
            }
            fn reveal(&self) -> Reveal<'_> {
                self.global()
            }
            fn theme(&self) -> Theme<'_> {
                self.global()
            }
            fn nav(&self) -> Nav<'_> {
                self.global()
            }
        }
    };
}
models!(FlyoutWindow);
#[cfg(debug_assertions)]
models!(Gallery);

/// What a view's `fill` gets.
pub struct Ctx<'a> {
    pub snapshot: &'a HostSnapshot,
    /// The app of a panel or of one app's history.
    pub app: Option<&'a str>,
    pub confirms: &'a Confirms,
    pub icons: &'a mut Icons,
    pub now: Instant,
    /// The first fill since this view (with this app) began to show: the
    /// window opened on it, Nav went to it, Back came back to it, or a new
    /// window was made. Today's views mount then: read a history, forget a
    /// "Copied" from before. False on the refills of every new snapshot.
    pub arrived: bool,
    /// The recent warnings, newest first (Recent warnings): the log's
    /// (`intent::warnings`) in the window, the shot's in a golden picture.
    pub warnings: &'a [WarningView],
}

/// One picture of a view for its golden images,
/// `native/tests/goldens/view-<name>/<state>-<theme>.png`: the view in the
/// shell's window, filled from a fixture by the view's own `fill`, at a
/// density and a height limit, in light, dark and High Contrast. Each view
/// module lists its own (`SHOTS`); adding one touches no other file.
#[derive(Debug, Clone, Copy)]
pub struct Shot {
    /// The picture's name (`busy`, `compact-tall`, `armed`).
    pub state: &'static str,
    /// A snapshot in `native/fixtures/<fixture>.json` (read only).
    pub fixture: &'static str,
    /// The app of a panel or of one app's history; "" for none.
    pub app: &'static str,
    /// Compact rows (D35).
    pub compact: bool,
    /// The window's height limit: 400, 500 or 600 (D35).
    pub height: u32,
    /// A state no fixture has, set up in the view's own module: a change to
    /// the fixture's snapshot (a long name, an app busy stopping), recent
    /// warnings, an armed action. Runs after `compact` and `height` are
    /// applied, before the view is filled.
    pub stage: Option<fn(&mut Stage)>,
}

impl Shot {
    /// A shot of `fixture` in Normal rows, with the short window.
    pub const fn of(state: &'static str, fixture: &'static str) -> Shot {
        Shot {
            state,
            fixture,
            app: "",
            compact: false,
            height: 400,
            stage: None,
        }
    }
}

/// What a shot's `stage` may change before its view is filled.
pub struct Stage<'a> {
    /// The fixture's snapshot (a copy: the fixture file stays as it is).
    pub snapshot: &'a mut HostSnapshot,
    /// The recent warnings the view gets (`Ctx::warnings`), newest first;
    /// none unless the stage adds some.
    pub warnings: &'a mut Vec<WarningView>,
    /// The armed actions: `confirms.press(confirm::key(app, action, None),
    /// true, Instant::now())` shows that action armed.
    pub confirms: &'a mut Confirms,
}

/// What Escape does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Escape {
    Hide,
    Back,
}

pub struct Router {
    view: View,
    app: Option<String>,
    back: Vec<(View, Option<String>)>,
    pub confirms: Confirms,
    pub icons: Icons,
    /// The view (and app) the last fill filled, so the next fill knows
    /// whether the view just arrived (`Ctx::arrived`); `None` after an open.
    shown: Option<(View, Option<String>)>,
    /// Fixed recent warnings (a golden picture's); `None`: the log's.
    pub warnings: Option<Vec<WarningView>>,
}

impl Default for Router {
    fn default() -> Self {
        Router {
            view: View::Hub,
            app: None,
            back: Vec::new(),
            confirms: Confirms::default(),
            icons: Icons::default(),
            shown: None,
            warnings: None,
        }
    }
}

impl Router {
    pub fn view(&self) -> View {
        self.view
    }

    pub fn app(&self) -> Option<&str> {
        self.app.as_deref()
    }

    /// Opens a view; `id` names the app of a panel or of a history. True
    /// when the view changed (the window then moves the focus to its top).
    pub fn go(&mut self, view: View, id: &str) -> bool {
        let app = (!id.is_empty()).then(|| id.to_string());
        if view == self.view && app == self.app {
            return false;
        }
        self.back.push((self.view, self.app.take()));
        if view == View::Hub {
            self.back.clear();
        }
        self.view = view;
        self.app = app;
        // Armed actions belong to the view that armed them (today's
        // ActionButton keeps its state in the view).
        self.confirms.clear();
        true
    }

    /// Back to the view before (the hub when there is none).
    pub fn back(&mut self) {
        let (view, app) = self.back.pop().unwrap_or((View::Hub, None));
        self.view = view;
        self.app = app;
        self.confirms.clear();
    }

    /// Escape: back, or in the hub hide the window (today's window).
    pub fn escape(&mut self) -> Escape {
        if self.view == View::Hub {
            Escape::Hide
        } else {
            self.back();
            Escape::Back
        }
    }

    /// The window opens on `view` (the hub on every open by the tray icon,
    /// the status details from the tray's status line), with nothing to go
    /// back to but the hub, and nothing armed.
    pub fn open_at(&mut self, view: View, id: &str) {
        self.view = view;
        self.app = (!id.is_empty()).then(|| id.to_string());
        self.back.clear();
        self.confirms.clear();
        self.shown = None;
    }

    /// A new window (the old one was dropped): its icons are loaded again and
    /// nothing is armed. The view stays the one `open_at` chose, and arrives
    /// again in the new window's models.
    pub fn new_window(&mut self) {
        self.icons = Icons::default();
        self.confirms.clear();
        self.shown = None;
    }

    /// The snapshot no longer has an app the router remembers: a panel (or
    /// one app's history) whose app is gone falls back to the hub, as today
    /// (`main.tsx` shows the hub for a panel without its app), and the way
    /// back forgets views of gone apps. True when the view changed.
    pub fn forget_gone(&mut self, snapshot: &HostSnapshot) -> bool {
        let exists = |app: &Option<String>| match app {
            None => true,
            Some(id) => id == "n8tray" || snapshot.apps.iter().any(|a| &a.id == id),
        };
        self.back.retain(|(_, app)| exists(app));
        // Two entries that were apart may now be the same view in a row.
        self.back.dedup();
        if exists(&self.app) {
            return false;
        }
        self.open_at(View::Hub, "");
        true
    }

    /// Whether the view that shows arrives with this fill (`Ctx::arrived`):
    /// it is not the one the last fill filled, or the window opened since.
    fn arrives(&mut self) -> bool {
        let here = (self.view, self.app.clone());
        let arrived = self.shown.as_ref() != Some(&here);
        self.shown = Some(here);
        arrived
    }

    /// The title a screen reader hears when the view opens (the title bar's
    /// words; `Nav.title`).
    pub fn title(&self, snapshot: &HostSnapshot) -> String {
        match self.view {
            View::Hub => "N8 Tray".into(),
            View::AllApps => "All apps".into(),
            View::Panel => self
                .app
                .as_deref()
                .and_then(|id| snapshot.apps.iter().find(|a| a.id == id))
                .map(|a| a.name.clone())
                .unwrap_or_default(),
            View::Details => "Status details".into(),
            View::Settings => "Settings".into(),
            View::About => "About N8 Tray".into(),
            View::History => "Resource history".into(),
        }
    }

    /// Fills the view that shows from the snapshot and sets `Nav.view` and
    /// `Nav.title`. A view whose app left the snapshot falls back first
    /// (`forget_gone`); true then, so the window moves the focus to the
    /// new view's top.
    pub fn fill(&mut self, ui: &dyn Models, snapshot: &HostSnapshot) -> bool {
        let fell_back = self.forget_gone(snapshot);
        ui.nav().set_view(self.view);
        ui.nav().set_title(self.title(snapshot).into());
        let arrived = self.arrives();
        let app = self.app.clone();
        let live;
        let warnings: &[WarningView] = match &self.warnings {
            Some(fixed) => fixed,
            None => {
                live = super::intent::warnings();
                &live
            }
        };
        let mut ctx = Ctx {
            snapshot,
            app: app.as_deref(),
            confirms: &self.confirms,
            icons: &mut self.icons,
            now: Instant::now(),
            arrived,
            warnings,
        };
        fill_view(self.view, ui, &mut ctx);
        fell_back
    }
}

/// Fills one view (the router's, and the gallery's view pages).
pub fn fill_view(view: View, ui: &dyn Models, ctx: &mut Ctx) {
    match view {
        View::Hub => hub::fill(ui, ctx),
        View::AllApps => all_apps::fill(ui, ctx),
        View::Panel => panel::fill(ui, ctx),
        View::Details => details::fill(ui, ctx),
        View::Settings => settings::fill(ui, ctx),
        View::About => about::fill(ui, ctx),
        View::History => history::fill(ui, ctx),
    }
}

/// Connects every view's callbacks, once per window.
pub fn wire(ui: &dyn Models) {
    hub::wire(ui);
    all_apps::wire(ui);
    panel::wire(ui);
    details::wire(ui);
    settings::wire(ui);
    about::wire(ui);
    history::wire(ui);
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::super::confirm;
    use super::*;
    use crate::tests::fixture;

    #[test]
    fn back_and_escape_retrace_the_views() {
        let mut r = Router::default();
        assert_eq!(r.escape(), Escape::Hide);
        r.go(View::AllApps, "");
        r.go(View::Panel, "voicedock");
        assert_eq!(r.app(), Some("voicedock"));
        assert_eq!(r.escape(), Escape::Back);
        assert_eq!(r.view(), View::AllApps);
        r.back();
        assert_eq!(r.view(), View::Hub);
        r.back();
        assert_eq!(r.view(), View::Hub, "the hub is the bottom");
        r.go(View::Details, "");
        r.go(View::Hub, "");
        r.back();
        assert_eq!(r.view(), View::Hub, "going home forgets the way");
    }

    /// Every open shows the hub; the tray's status line opens the details
    /// with only the hub behind them.
    #[test]
    fn an_open_starts_over_at_its_view() {
        let mut r = Router::default();
        r.go(View::AllApps, "");
        r.go(View::Panel, "voicedock");
        r.open_at(View::Hub, "");
        assert_eq!((r.view(), r.app()), (View::Hub, None));
        assert_eq!(r.escape(), Escape::Hide, "nothing to go back to");
        r.go(View::Settings, "");
        r.open_at(View::Details, "");
        assert_eq!(r.view(), View::Details);
        r.back();
        assert_eq!(r.view(), View::Hub, "the tray request cleared the way back");
        // A new window keeps the view it opens on.
        r.open_at(View::Details, "");
        r.new_window();
        assert_eq!(r.view(), View::Details);
    }

    fn arm(r: &mut Router, app: &str) -> confirm::Key {
        let key = confirm::key(app, "stop", None);
        r.confirms.press(key.clone(), true, Instant::now());
        key
    }

    /// Armed actions belong to the view that armed them: Stop armed on a hub
    /// row is not armed in that app's panel, nor after going back.
    #[test]
    fn a_view_change_disarms_everything() {
        let now = Instant::now();
        let mut r = Router::default();
        let stop = arm(&mut r, "voicedock");
        assert!(r.confirms.is_armed(&stop, now));
        assert!(r.go(View::Panel, "voicedock"));
        assert!(!r.confirms.is_armed(&stop, now), "not armed in the panel");
        let stop = arm(&mut r, "voicedock");
        r.back();
        assert!(!r.confirms.is_armed(&stop, now), "nor back in the hub");
        let stop = arm(&mut r, "voicedock");
        assert!(!r.go(View::Hub, ""), "the same view is no change");
        assert!(r.confirms.is_armed(&stop, now), "and keeps what is armed");
        r.open_at(View::Hub, "");
        assert!(!r.confirms.is_armed(&stop, now), "an open disarms");
        let stop = arm(&mut r, "voicedock");
        r.new_window();
        assert!(!r.confirms.is_armed(&stop, now));
    }

    /// A panel whose app left the snapshot falls back to the hub, and the
    /// way back forgets the gone app's views.
    #[test]
    fn a_gone_apps_views_fall_back_to_the_hub() {
        let s = fixture("busy");
        let mut gone = s.clone();
        gone.apps.retain(|a| a.id != "voicedock");
        let other = gone.apps[0].id.clone();

        let mut r = Router::default();
        r.go(View::Panel, "voicedock");
        assert!(!r.forget_gone(&s), "still there");
        assert!(r.forget_gone(&gone));
        assert_eq!((r.view(), r.app()), (View::Hub, None));

        r.go(View::Panel, &other);
        r.go(View::History, "voicedock");
        // From the gone app's history: to the hub, nothing behind.
        assert!(r.forget_gone(&gone));
        assert_eq!(r.view(), View::Hub);

        r.go(View::Panel, "voicedock");
        r.go(View::History, "n8tray");
        r.go(View::Details, "");
        assert!(!r.forget_gone(&gone), "the details need no app");
        r.back();
        assert_eq!((r.view(), r.app()), (View::History, Some("n8tray")));
        r.back();
        assert_eq!(r.view(), View::Hub, "the gone panel was dropped");
    }

    /// A view arrives on its first fill (today's views mount then: History
    /// reads its data), not on the refills of later snapshots.
    #[test]
    fn a_view_arrives_once_per_visit() {
        let mut r = Router::default();
        assert!(r.arrives(), "the first fill");
        assert!(!r.arrives(), "a refill");
        r.go(View::History, "");
        assert!(r.arrives());
        assert!(!r.arrives());
        r.go(View::History, "voicedock");
        assert!(r.arrives(), "another app's history");
        r.back();
        assert!(r.arrives(), "back to the history of every app");
        r.open_at(View::History, "");
        assert!(r.arrives(), "the window opened again on the same view");
        assert!(!r.arrives());
        r.new_window();
        assert!(r.arrives(), "a new window's models are empty");
        // The same view asked again is no visit.
        assert!(!r.go(View::History, ""));
        assert!(!r.arrives());
    }

    #[test]
    fn each_view_has_its_title_bars_title() {
        let s = fixture("busy");
        let mut r = Router::default();
        assert_eq!(r.title(&s), "N8 Tray");
        r.go(View::Panel, "voicedock");
        assert_eq!(r.title(&s), "VoiceDock");
        r.go(View::Details, "");
        assert_eq!(r.title(&s), "Status details");
        r.go(View::History, "");
        assert_eq!(r.title(&s), "Resource history");
    }

    /// The view files' types reach Rust through one chain of `export *`
    /// (Slint allows one per file): `main.slint` exports the hub's model
    /// file, each model file the next one's, History's ends it. A model file
    /// holds no component (an exported component that is not a window is a
    /// build warning), and a view file exports nothing whole.
    #[test]
    fn the_model_files_form_one_export_chain() {
        let ui = Path::new(env!("CARGO_MANIFEST_DIR")).join("ui");
        let read = |p: &str| std::fs::read_to_string(ui.join(p)).unwrap();
        let star = |text: &str| -> Vec<String> {
            text.lines()
                .filter_map(|l| l.trim().strip_prefix("export * from \""))
                .map(|l| l.trim_end_matches("\";").to_string())
                .collect()
        };
        let chain = [
            "hub", "all-apps", "panel", "details", "settings", "about", "history",
        ];
        assert_eq!(star(&read("main.slint")), ["views/hub-model.slint"]);
        for (i, name) in chain.iter().enumerate() {
            let model = read(&format!("views/{name}-model.slint"));
            let next: Vec<String> = chain
                .get(i + 1)
                .map(|n| format!("{n}-model.slint"))
                .into_iter()
                .collect();
            assert_eq!(star(&model), next, "{name}-model.slint");
            assert!(
                !model.lines().any(|l| {
                    let l = l.trim_start();
                    l.starts_with("component ") || l.starts_with("export component ")
                }),
                "{name}-model.slint has a component"
            );
            let view = read(&format!("views/{name}.slint"));
            assert!(star(&view).is_empty(), "{name}.slint");
            // Every exported type starts with the view's name (`AllApps...`),
            // so two lanes never export the same name through the chain
            // (Slint only warns when they do, and Rust then sees one).
            let prefix: String = name
                .split('-')
                .map(|w| w[..1].to_uppercase() + &w[1..])
                .collect();
            let mut names = Vec::new();
            for line in model.lines() {
                let line = line.trim_start();
                for kind in ["export struct ", "export enum ", "export global "] {
                    if let Some(rest) = line.strip_prefix(kind) {
                        let type_name: String = rest
                            .chars()
                            .take_while(|c| c.is_alphanumeric() || *c == '-' || *c == '_')
                            .collect();
                        names.push(type_name);
                    }
                }
            }
            assert!(!names.is_empty(), "{name}-model.slint exports nothing");
            for type_name in names {
                assert!(
                    type_name.starts_with(&prefix),
                    "{name}-model.slint exports {type_name}: its types start with {prefix}"
                );
            }
        }
    }
}
